html { --miku-state-peek: url('data:image/webp;base64,'); }

html { --miku-state-listening: url('data:image/webp;base64,'); }

html { --miku-state-thinking: url('data:image/webp;base64,'); }

html { --miku-state-done: url('data:image/webp;base64,'); }

html { --miku-state-empty: url('data:image/webp;base64,'); }

html:root .settings-preview-layout #general > .section-title-row::after,
html:root .settings-preview-layout #playback > .section-title-row::after {
  content: '';
  display: block;
  width: 72px;
  height: 64px;
  flex: 0 0 72px;
  margin-left: auto;
  background: var(--miku-state-peek) center / contain no-repeat;
  pointer-events: none;
}

html:root .settings-preview-layout #playback > .section-title-row::after {
  background-image: var(--miku-state-listening);
}

