html:root .home .empty-stage::before,
html:root .streaming-page .search-view .streaming-placeholder:has(> .pi-search)::before {
  content: '';
  display: block;
  position: relative;
  width: 144px;
  height: 144px;
  flex: 0 0 auto;
  margin: 0 auto 12px;
  background: var(--miku-state-empty) center / contain no-repeat;
  pointer-events: none;
}

html:root .streaming-page .search-view .streaming-placeholder:has(> .pi-search)::before {
  background-image: var(--miku-state-thinking);
}

html:root :is(.song-list .empty-state, .streaming-page .library-view .empty-state) > .empty-icon,
html:root .home .empty-stage > .empty-badge,
html:root .streaming-page .search-view .streaming-placeholder > .pi-search {
